"""Promo codes: description, registry, expiry and usage limits.

Order conditions (minimum amount, participating lines) are checked by
:func:`shop.pricing.calculate_total`; the registry only knows about existence,
validity period and the usage limit.
"""

from __future__ import annotations

import logging
import threading
from collections.abc import Iterable
from dataclasses import dataclass, field
from datetime import datetime
from decimal import Decimal
from enum import StrEnum

from .catalog import Category, normalize_key
from .clock import Clock, SystemClock
from .errors import (
    PromoConditionsError,
    PromoExpiredError,
    UnknownPromoCodeError,
    ValidationError,
)
from .money import ZERO, to_money

logger = logging.getLogger(__name__)

HUNDRED = Decimal("100")


class DiscountKind(StrEnum):
    PERCENT = "percent"
    FIXED = "fixed"


def _require_decimal(value: object, what: str) -> Decimal:
    if isinstance(value, bool) or not isinstance(value, (Decimal, int)):
        raise ValidationError(f"{what} must be Decimal or int")
    amount = Decimal(value)
    if not amount.is_finite():
        raise ValidationError(f"{what} must be finite")
    return amount


def _require_aware(at: object, what: str) -> None:
    if not isinstance(at, datetime):
        raise ValidationError(f"{what} must be a datetime")
    if at.tzinfo is None or at.utcoffset() is None:
        raise ValidationError(f"{what} must be timezone-aware")


@dataclass(frozen=True)
class PromoCode:
    code: str
    kind: DiscountKind
    value: Decimal
    min_order_amount: Decimal = ZERO
    starts_at: datetime | None = None
    expires_at: datetime | None = None
    max_uses: int | None = None
    excluded_categories: frozenset[Category] = field(default_factory=frozenset)

    def __post_init__(self) -> None:
        code = normalize_key(self.code)
        if not code:
            raise ValidationError("promo code must not be empty")
        object.__setattr__(self, "code", code)
        if not isinstance(self.kind, DiscountKind):
            raise ValidationError(f"kind of {code} must be a DiscountKind")

        value = _require_decimal(self.value, f"value of {code}")
        if self.kind is DiscountKind.PERCENT:
            if not Decimal("0") < value <= HUNDRED:
                raise ValidationError(f"percent of {code} must be in (0, 100]")
        else:
            if value <= 0:
                raise ValidationError(f"fixed discount of {code} must be positive")
            if to_money(value) != value:
                raise ValidationError(f"fixed discount of {code} has more than two digits")
            value = to_money(value)
        object.__setattr__(self, "value", value)

        minimum = _require_decimal(self.min_order_amount, f"min_order_amount of {code}")
        if minimum < 0 or to_money(minimum) != minimum:
            raise ValidationError(f"min_order_amount of {code} must be a non-negative amount")
        object.__setattr__(self, "min_order_amount", to_money(minimum))

        if self.starts_at is not None:
            _require_aware(self.starts_at, f"starts_at of {code}")
        if self.expires_at is not None:
            _require_aware(self.expires_at, f"expires_at of {code}")
        if (
            self.starts_at is not None
            and self.expires_at is not None
            and self.starts_at >= self.expires_at
        ):
            raise ValidationError(f"starts_at of {code} must be before expires_at")

        if self.max_uses is not None and (
            isinstance(self.max_uses, bool)
            or not isinstance(self.max_uses, int)
            or self.max_uses < 1
        ):
            raise ValidationError(f"max_uses of {code} must be an integer >= 1")

        categories = frozenset(self.excluded_categories)
        if not all(isinstance(c, Category) for c in categories):
            raise ValidationError(f"excluded_categories of {code} must be Category values")
        object.__setattr__(self, "excluded_categories", categories)

    def is_active_at(self, moment: datetime) -> bool:
        """Half-open validity interval ``[starts_at, expires_at)``."""
        if self.starts_at is not None and moment < self.starts_at:
            return False
        if self.expires_at is not None and moment >= self.expires_at:
            return False
        return True


class PromoRegistry:
    """In-memory registry of promo codes with usage counters."""

    def __init__(
        self, codes: Iterable[PromoCode] = (), *, clock: Clock | None = None
    ) -> None:
        self._clock = clock or SystemClock()
        self._codes: dict[str, PromoCode] = {}
        self._uses: dict[str, int] = {}
        self._lock = threading.Lock()
        for promo in codes:
            self.add(promo)

    def add(self, promo: PromoCode) -> None:
        with self._lock:
            if promo.code in self._codes:
                raise ValidationError(f"duplicate promo code: {promo.code}")
            self._codes[promo.code] = promo
            self._uses[promo.code] = 0
        logger.debug("promo: added %s", promo.code)

    def resolve(self, code: str) -> PromoCode:
        """Find a code and check it exists, is active now and has uses left."""
        with self._lock:
            return self._resolve_locked(code)

    def uses(self, code: str) -> int:
        with self._lock:
            return self._uses[self._lookup(code).code]

    def redeem(self, code: str) -> PromoCode:
        """Atomically re-check the code and count one more use."""
        with self._lock:
            promo = self._resolve_locked(code)
            self._uses[promo.code] += 1
            return promo

    def release(self, code: str) -> None:
        """Give back one use (never below zero); the validity period is not checked."""
        key = normalize_key(code)
        with self._lock:
            if key not in self._codes:
                logger.warning("promo: release of unknown code %r ignored", key)
                return
            self._uses[key] = max(0, self._uses[key] - 1)

    def _lookup(self, code: str) -> PromoCode:
        key = normalize_key(code)
        try:
            return self._codes[key]
        except KeyError:
            raise UnknownPromoCodeError(f"unknown promo code: {key!r}") from None

    def _resolve_locked(self, code: str) -> PromoCode:
        promo = self._lookup(code)
        if not promo.is_active_at(self._clock.now()):
            raise PromoExpiredError(f"promo code {promo.code} is not active")
        if promo.max_uses is not None and self._uses[promo.code] >= promo.max_uses:
            raise PromoConditionsError(f"promo code {promo.code} usage limit reached")
        return promo
"""Order total calculation: line amounts, tax and shipping.

Rules (see README):

* line amount = unit price x quantity;
* tax is charged on top of the price, per line, at the rate of the line's category,
  and rounded per line (ROUND_HALF_UP); the order tax is the sum of line taxes;
* shipping is a flat fee, free when the goods subtotal reaches the threshold;
  carts with gift cards only are not shipped at all;
* shipping is not taxed;
* a promo code discount is spread over the participating lines (largest remainder
  method), tax is charged on the line amount after discount and the free shipping
  threshold is compared with the goods subtotal after discount.
"""

from __future__ import annotations

import logging
from collections.abc import Mapping
from dataclasses import dataclass, field
from decimal import ROUND_DOWN, Decimal, localcontext
from types import MappingProxyType

from .catalog import Cart, Category
from .errors import EmptyCartError, PromoConditionsError, ValidationError
from .money import CENT, ZERO, quantize_money, sum_money
from .promo import DiscountKind, PromoCode

logger = logging.getLogger(__name__)

DEFAULT_TAX_RATE = Decimal("0.20")
DEFAULT_TAX_RATES: Mapping[Category, Decimal] = MappingProxyType(
    {
        Category.BOOKS: Decimal("0.10"),
        Category.FOOD: Decimal("0.10"),
        Category.GIFT_CARD: Decimal("0"),
    }
)


@dataclass(frozen=True)
class TaxPolicy:
    rates: Mapping[Category, Decimal] = field(default_factory=lambda: DEFAULT_TAX_RATES)
    default_rate: Decimal = DEFAULT_TAX_RATE

    def __post_init__(self) -> None:
        for rate in (*self.rates.values(), self.default_rate):
            if not Decimal("0") <= rate < Decimal("1"):
                raise ValidationError(f"tax rate out of range: {rate}")

    def rate_for(self, category: Category) -> Decimal:
        return self.rates.get(category, self.default_rate)

    def tax_for(self, category: Category, taxable_amount: Decimal) -> Decimal:
        return quantize_money(taxable_amount * self.rate_for(category))


@dataclass(frozen=True)
class ShippingPolicy:
    fee: Decimal = Decimal("299.00")
    free_threshold: Decimal | None = Decimal("3000.00")

    def __post_init__(self) -> None:
        if self.fee < 0:
            raise ValidationError("shipping fee must not be negative")
        if self.free_threshold is not None and self.free_threshold < 0:
            raise ValidationError("free shipping threshold must not be negative")

    def cost_for(self, goods_amount: Decimal, *, needs_delivery: bool) -> Decimal:
        if not needs_delivery:
            return ZERO
        if self.free_threshold is not None and goods_amount >= self.free_threshold:
            return ZERO
        return quantize_money(self.fee)


@dataclass(frozen=True)
class LineTotal:
    sku: str
    category: Category
    quantity: int
    unit_price: Decimal
    amount: Decimal
    tax: Decimal
    discount: Decimal = ZERO


@dataclass(frozen=True)
class OrderTotal:
    lines: tuple[LineTotal, ...]
    subtotal: Decimal
    shipping: Decimal
    tax: Decimal
    total: Decimal
    discount: Decimal = ZERO

    @property
    def items_count(self) -> int:
        return sum(line.quantity for line in self.lines)


DEFAULT_SHIPPING = ShippingPolicy()
DEFAULT_TAX = TaxPolicy()


def _discount_amount(promo: PromoCode, base: Decimal) -> Decimal:
    if promo.kind is DiscountKind.PERCENT:
        return quantize_money(base * promo.value / 100)
    return min(promo.value, base)


def _spread_discount(discount: Decimal, amounts: list[Decimal]) -> list[Decimal]:
    """Largest remainder method; the result always sums to ``discount``."""
    base = sum(amounts, ZERO)
    with localcontext() as ctx:
        ctx.prec = 60
        exacts = [discount * amount / base for amount in amounts]
        floors = [exact.quantize(CENT, rounding=ROUND_DOWN) for exact in exacts]
        remainders = [exact - floor for exact, floor in zip(exacts, floors)]
        spare = int((discount - sum(floors, ZERO)) / CENT)
    order = sorted(range(len(amounts)), key=lambda i: (-remainders[i], i))
    for i in order[:spare]:
        floors[i] += CENT
    return floors


def calculate_total(
    cart: Cart,
    shipping: ShippingPolicy | None = None,
    tax: TaxPolicy | None = None,
    promo: PromoCode | None = None,
) -> OrderTotal:
    """Calculate the totals of ``cart``. Pure function: does not modify the cart.

    ``promo`` is applied as is: validity period and usage limit are checked by the
    :class:`~shop.promo.PromoRegistry`, only order conditions are checked here.
    """
    if cart.is_empty:
        raise EmptyCartError("cannot calculate total of an empty cart")
    shipping = shipping or DEFAULT_SHIPPING
    tax = tax or DEFAULT_TAX

    cart_lines = cart.lines
    discounts = [ZERO] * len(cart_lines)
    discount = ZERO
    if promo is not None:
        eligible = [
            i
            for i, line in enumerate(cart_lines)
            if line.product.category is not Category.GIFT_CARD
            and line.product.category not in promo.excluded_categories
        ]
        if not eligible:
            raise PromoConditionsError(f"promo code {promo.code}: no eligible items in the cart")
        base = sum_money(cart_lines[i].amount for i in eligible)
        if base < promo.min_order_amount:
            raise PromoConditionsError(
                f"promo code {promo.code}: order amount {base} is below {promo.min_order_amount}"
            )
        discount = _discount_amount(promo, base)
        shares = _spread_discount(discount, [cart_lines[i].amount for i in eligible])
        for i, share in zip(eligible, shares):
            discounts[i] = share

    lines: list[LineTotal] = []
    for cart_line, line_discount in zip(cart_lines, discounts):
        product = cart_line.product
        amount = cart_line.amount
        lines.append(
            LineTotal(
                sku=product.sku,
                category=product.category,
                quantity=cart_line.quantity,
                unit_price=product.price,
                amount=amount,
                tax=tax.tax_for(product.category, amount - line_discount),
                discount=line_discount,
            )
        )

    subtotal = sum_money(line.amount for line in lines)
    needs_delivery = any(line.product.is_physical for line in cart_lines)
    shipping_cost = shipping.cost_for(subtotal - discount, needs_delivery=needs_delivery)
    tax_total = sum_money(line.tax for line in lines)
    total = subtotal - discount + shipping_cost + tax_total

    logger.debug(
        "total: subtotal=%s discount=%s shipping=%s tax=%s total=%s",
        subtotal,
        discount,
        shipping_cost,
        tax_total,
        total,
    )
    return OrderTotal(
        lines=tuple(lines),
        subtotal=subtotal,
        shipping=shipping_cost,
        tax=tax_total,
        total=total,
        discount=discount,
    )

